"""Add order header/line projections and atomic synchronization.

Approved snapshots and receipt counters are projected from authoritative records.
Invoice obligations and action authorization remain application responsibilities.
"""
from alembic import op

revision = '0006_proc_orders'
down_revision = '0005_proc_offers'
branch_labels = None
depends_on = None

SQL = "-- Approved line facts are snapshots; later quotation changes do not rewrite them.\nCREATE TABLE public.proc_orders (\n    tenant varchar(64) NOT NULL,\n    id varchar(64) NOT NULL,\n    source_revision integer NOT NULL CHECK (source_revision >= 1),\n    rfq_id varchar(64) NOT NULL,\n    plan_id varchar(64) NOT NULL,\n    intent_id varchar(64) NOT NULL,\n    external_id varchar(80) NOT NULL,\n    status text NOT NULL CHECK (status IN ('confirmed','part_received','received','closed')),\n    total numeric(16,2) NOT NULL CHECK (total > 0),\n    currency text NOT NULL CHECK (currency='AED'),\n    simulated boolean NOT NULL,\n    closed_at timestamptz,\n    PRIMARY KEY (tenant,id),\n    UNIQUE (tenant,external_id),\n    UNIQUE (tenant,intent_id),\n    UNIQUE (tenant,plan_id),\n    CHECK ((status='closed') = (closed_at IS NOT NULL)),\n    FOREIGN KEY (tenant,rfq_id) REFERENCES public.proc_rfqs(tenant,id) DEFERRABLE INITIALLY DEFERRED\n);\nCREATE TABLE public.proc_order_lines (\n    tenant varchar(64) NOT NULL,\n    order_id varchar(64) NOT NULL,\n    line_index integer NOT NULL CHECK (line_index >= 0),\n    offer_id varchar(64) NOT NULL,\n    offer_revision integer NOT NULL CHECK (offer_revision >= 1),\n    supplier_id varchar(64) NOT NULL,\n    sku varchar(80) NOT NULL,\n    quantity integer NOT NULL CHECK (quantity > 0),\n    unit text NOT NULL CHECK (unit='piece'),\n    unit_price numeric(14,2) NOT NULL CHECK (unit_price > 0),\n    freight_per_piece numeric(14,2) NOT NULL CHECK (freight_per_piece >= 0),\n    fixed_freight numeric(14,2) NOT NULL CHECK (fixed_freight >= 0),\n    line_total numeric(16,2) NOT NULL,\n    received integer NOT NULL CHECK (received >= 0 AND received <= quantity),\n    accepted integer NOT NULL CHECK (accepted >= 0),\n    rejected integer NOT NULL CHECK (rejected >= 0),\n    quarantine integer NOT NULL CHECK (quarantine >= 0),\n    approved_snapshot jsonb NOT NULL CHECK (jsonb_typeof(approved_snapshot)='object'),\n    PRIMARY KEY (tenant,order_id,line_index),\n    CHECK (received = accepted + rejected + quarantine),\n    CHECK (line_total = (unit_price + freight_per_piece) * quantity + fixed_freight),\n    FOREIGN KEY (tenant,order_id) REFERENCES public.proc_orders(tenant,id) DEFERRABLE INITIALLY DEFERRED,\n    FOREIGN KEY (tenant,offer_id) REFERENCES public.proc_offers(tenant,id) DEFERRABLE INITIALLY DEFERRED,\n    FOREIGN KEY (tenant,supplier_id) REFERENCES public.proc_suppliers(tenant,id) DEFERRABLE INITIALLY DEFERRED\n);\nCREATE INDEX ix_proc_orders_rfq_status ON public.proc_orders(tenant,rfq_id,status);\nCREATE INDEX ix_proc_order_lines_supplier ON public.proc_order_lines(tenant,supplier_id,sku);\nDO $$ DECLARE t text;\nBEGIN\n    FOREACH t IN ARRAY ARRAY['proc_orders','proc_order_lines'] LOOP\n        EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY',t);\n        EXECUTE format('ALTER TABLE public.%I FORCE ROW LEVEL SECURITY',t);\n        EXECUTE format('CREATE POLICY tenant_scope ON public.%I TO supplypilot_app USING (tenant = NULLIF(current_setting(''supplypilot.tenant'',true),'''')) WITH CHECK (tenant = NULLIF(current_setting(''supplypilot.tenant'',true),''''))',t);\n        EXECUTE format('CREATE POLICY migration_owner ON public.%I TO supplypilot_migrator USING (true) WITH CHECK (true)',t);\n        EXECUTE format('REVOKE ALL ON TABLE public.%I FROM PUBLIC, supplypilot_app',t);\n        EXECUTE format('GRANT SELECT ON TABLE public.%I TO supplypilot_app',t);\n    END LOOP;\nEND $$;\n\nCREATE FUNCTION public.sync_procurement_order()\nRETURNS trigger LANGUAGE plpgsql SECURITY DEFINER\nSET search_path=pg_catalog,pg_temp\nAS $$\nDECLARE d jsonb; l jsonb; amount numeric; key text; actual_total numeric;\nBEGIN\n    IF TG_OP='UPDATE' AND (OLD.kind='order' OR NEW.kind='order') AND\n       (OLD.tenant,OLD.id,OLD.kind) IS DISTINCT FROM (NEW.tenant,NEW.id,NEW.kind) THEN\n        RAISE EXCEPTION 'Order identity, tenant and kind are immutable' USING ERRCODE='23514';\n    END IF;\n    IF TG_OP='DELETE' THEN\n        IF OLD.kind='order' THEN\n            DELETE FROM public.proc_order_lines WHERE tenant=OLD.tenant AND order_id=OLD.id;\n            DELETE FROM public.proc_orders WHERE tenant=OLD.tenant AND id=OLD.id;\n        END IF;\n        RETURN OLD;\n    END IF;\n    IF NEW.kind<>'order' THEN RETURN NEW; END IF;\n    d:=NEW.data::jsonb;\n    IF jsonb_typeof(d->'lines') IS DISTINCT FROM 'array' THEN\n        RAISE EXCEPTION 'Order lines must be an array' USING ERRCODE='23514';\n    END IF;\n    IF jsonb_array_length(d->'lines')=0 THEN\n        RAISE EXCEPTION 'Order requires at least one line' USING ERRCODE='23514';\n    END IF;\n    amount:=(d->>'total')::numeric;\n    IF amount IS DISTINCT FROM round(amount,2) OR amount::text IN ('NaN','Infinity','-Infinity') THEN\n        RAISE EXCEPTION 'Order total must be finite with at most two decimal places' USING ERRCODE='23514';\n    END IF;\n    INSERT INTO public.proc_orders VALUES(NEW.tenant,NEW.id,NEW.revision,d->>'rfq_id',d->>'plan_id',\n        d->>'intent_id',d->>'external_id',d->>'status',(d->>'total')::numeric,d->>'currency',\n        (d->>'simulated')::boolean,(d->>'closed_at')::timestamptz)\n    ON CONFLICT(tenant,id) DO UPDATE SET source_revision=EXCLUDED.source_revision,\n        rfq_id=EXCLUDED.rfq_id,plan_id=EXCLUDED.plan_id,intent_id=EXCLUDED.intent_id,\n        external_id=EXCLUDED.external_id,status=EXCLUDED.status,total=EXCLUDED.total,\n        currency=EXCLUDED.currency,simulated=EXCLUDED.simulated,closed_at=EXCLUDED.closed_at;\n    DELETE FROM public.proc_order_lines WHERE tenant=NEW.tenant AND order_id=NEW.id;\n    FOR l IN SELECT value FROM jsonb_array_elements(d->'lines') LOOP\n        FOREACH key IN ARRAY ARRAY['unit_price','freight_per_piece','fixed_freight','line_total'] LOOP\n            amount:=COALESCE(l->>key,CASE WHEN key='fixed_freight' THEN '0.00' END)::numeric;\n            IF amount IS DISTINCT FROM round(amount,2) OR amount::text IN ('NaN','Infinity','-Infinity') THEN\n                RAISE EXCEPTION 'Order money must be finite with at most two decimal places' USING ERRCODE='23514';\n            END IF;\n        END LOOP;\n        IF l->>'currency' IS DISTINCT FROM d->>'currency' THEN\n            RAISE EXCEPTION 'Order line currency differs from header' USING ERRCODE='23514';\n        END IF;\n    END LOOP;\n    INSERT INTO public.proc_order_lines\n    SELECT NEW.tenant,NEW.id,(x.n-1)::integer,x.v->>'offer_id',(x.v->>'offer_revision')::integer,\n        x.v->>'supplier_id',x.v->>'sku',(x.v->>'quantity')::integer,x.v->>'unit',\n        (x.v->>'unit_price')::numeric,(x.v->>'freight_per_piece')::numeric,\n        COALESCE(x.v->>'fixed_freight','0.00')::numeric,(x.v->>'line_total')::numeric,\n        (x.v->>'received')::integer,(x.v->>'accepted')::integer,(x.v->>'rejected')::integer,\n        (x.v->>'quarantine')::integer,x.v-ARRAY['received','accepted','rejected','quarantine']\n    FROM jsonb_array_elements(d->'lines') WITH ORDINALITY x(v,n);\n    SELECT sum(line_total) INTO actual_total FROM public.proc_order_lines\n        WHERE tenant=NEW.tenant AND order_id=NEW.id;\n    IF actual_total IS DISTINCT FROM (d->>'total')::numeric THEN\n        RAISE EXCEPTION 'Order total differs from line totals' USING ERRCODE='23514';\n    END IF;\n    IF d->>'status'='closed' AND EXISTS(SELECT 1 FROM public.proc_order_lines\n        WHERE tenant=NEW.tenant AND order_id=NEW.id AND accepted<>quantity) THEN\n        RAISE EXCEPTION 'Closed order has unaccepted quantities' USING ERRCODE='23514';\n    END IF;\n    RETURN NEW;\nEND $$;\nREVOKE ALL ON FUNCTION public.sync_procurement_order() FROM PUBLIC,supplypilot_app;\nCREATE TRIGGER records_order_sync AFTER INSERT OR UPDATE OR DELETE ON public.records\nFOR EACH ROW EXECUTE FUNCTION public.sync_procurement_order();\nUPDATE public.records SET data=data WHERE kind='order';\n"


def upgrade():
    op.execute(SQL)


def downgrade():
    raise RuntimeError('Use the verified backup rollback procedure; automatic order projection removal is disabled.')
